import metadata from './block.json';

const { attributes: blockAttributes, supports: blockSupports } = metadata;

type SeparatorAttributes = Record< string, unknown > & {
	color?: string;
	customColor?: string;
};

/**
 * Deprecation for the `color` and `customColor` attributes, replaced by the
 * color block support.
 *
 * Attribute-only: the color classes and styles of that version are
 * regenerated by the parser from the migrated attributes.
 */
const legacyColors = {
	attributes: {
		...blockAttributes,
		color: {
			type: 'string',
		},
		customColor: {
			type: 'string',
		},
	},
	supports: blockSupports,
	isEligible( { color, customColor }: SeparatorAttributes ) {
		return !! color || !! customColor;
	},
	migrate( attributes: SeparatorAttributes ) {
		const { color, customColor, ...restAttributes } = attributes;
		return {
			...restAttributes,
			backgroundColor: color ? color : undefined,
			opacity: 'css',
			style: customColor
				? { color: { background: customColor } }
				: undefined,
			tagName: 'hr',
		};
	},
};

export default [ legacyColors ];
